  'Battery & background activity': 'Батерия и фонова активност',
  'The open computer updates live. Less frequent checks of other computers reduce network activity. Connections pause while the app is in the background; notifications and Live Activities are managed in Notifications. Disabled widgets keep their last saved snapshot.':
    'Отворените компютърни актуализации на живо. По-рядките проверки на други компютри намаляват мрежовата активност. Връзките се поставят на пауза, докато приложението е във фонов режим; известията и дейностите на живо се управляват в Известия. Деактивираните приспособления запазват последната си запазена моментна снимка.',
