    'Забравянето премахва тази връзка от телефона ви. Работата по компютъра продължава.',
  'Forget computer': 'Забравете компютъра',
  'Forget {value0}?': 'Забравете {value0}?',
  'This phone’s access is removed from the computer too. Connecting again needs a new pairing code. Work on the computer continues.':
    'Достъпът на този телефон също е премахнат от компютъра. Повторното свързване изисква нов код за сдвояване. Работата по компютъра продължава.',
  Forget: 'Забравете',
  'Conflicting edits are saved here while the runtime value stays in use. Select and copy an edit to recover it.':
    'Конфликтните редакции се записват тук, докато стойността за изпълнение остава в употреба. Изберете и копирайте редакция, за да я възстановите.',
  'No recovered edits.': 'Няма възстановени редакции.',
  'Load older edits': 'Зареждане на по-стари редакции',
  'Saved on {value0}. Discover and control simulators and connected phones on other paired computers over SSH.':
    'Запазено на {value0}. Открийте и управлявайте симулатори и свързани телефони на други сдвоени компютри през SSH.',
  'the current runtime': 'текущата среда за изпълнение',
  'This computer is offline. Reconnect to load or save device hosts. Your draft is kept here.':
    'Този компютър е офлайн. Свържете се отново, за да заредите или запазите хостовете на устройството. Вашата чернова се съхранява тук.',
