  'Retry device host settings': 'Опитайте отново с настройките на хоста на устройството',
  'Device Hub': 'Device Hub',
  'Enable device discovery and controls on this runtime. Turning it off keeps saved hosts and leaves devices running.':
    'Активирайте откриването на устройства и контролите в тази среда на изпълнение. Изключването му запазва запазените хостове и оставя устройствата да работят.',
  'Enable Device Hub': 'Активиране на Device Hub',
  'Remote device hosts': 'Хостове на отдалечено устройство',
