    'Дестинацията изисква актуализирано инсталирано време за изпълнение на Dovo и съществуващо сдвояване. SSH сам по себе си не предоставя достъп на Dovo.',
  'No remote device hosts yet. Local devices remain available.':
    'Все още няма хостове за отдалечени устройства. Локалните устройства остават налични.',
  'Add device host': 'Добавете хост на устройството',
