  'Local runtime (no remote default)':
    'Локално време за изпълнение (без дистанционно по подразбиране)',
  'Preselects this host in the desktop device picker. The mobile picker shows devices from all reachable hosts.':
    'Предварително избира този хост в инструмента за избор на настолни устройства. Инструментът за избор на мобилни устройства показва устройства от всички достъпни хостове.',
  'Remove device host': 'Премахнете хоста на устройството',
  'Remove device host?': 'Премахване на хоста на устройството?',
  'This removes the SSH device host configuration from this runtime. The destination pairing and its devices remain intact.':
    'Това премахва конфигурацията на хоста на SSH устройство от тази среда за изпълнение. Сдвояването на дестинацията и нейните устройства остават непокътнати.',
