  'This thread stays read-only. Retry the move, or cancel it. Cancel unlocks the thread only after {value0} confirms that it removed its copy. If {value1} already received the thread, cancel finishes the move instead.':
    'Тази нишка остава само за четене. Опитайте отново преместването или го отменете. Отказ отключва нишката само след като {value0} потвърди, че е премахнал своето копие. Ако {value1} вече е получил нишката, отмяната завършва преместването вместо това.',
