  '{value0} symbolic links skipped.': '{value0} символните връзки са пропуснати.',
  'Cancel move': 'Отмени преместването',
  'Cancel copy': 'Отказ от копиране',
  'Move the full saved conversation, checklist, attachments and files. Provider sessions and credentials stay here. The destination thread uses that computer’s default harness, with no more access than this thread has. Nothing runs until you send the next message there. You can change its model after it opens. This thread stays here, read-only, for recovery.':
    'Преместете пълния запазен разговор, контролен списък, прикачени файлове и файлове. Сесиите на доставчика и идентификационните данни остават тук. Целевата нишка използва снопа по подразбиране на този компютър, с не повече достъп от тази нишка. Нищо не се изпълнява, докато не изпратите следващото съобщение там. Можете да промените модела му, след като се отвори. Тази нишка остава тук, само за четене, за възстановяване.',
  'Copy files and local Git history. The source project and chats stay here. A new folder is created on the destination. Worktrees use its configured worktree directory.':
    'Копирайте файлове и локална Git история. Изходният проект и чатовете остават тук. Създава се нова папка на дестинацията. Worktrees използва своята конфигурирана директория worktree.',
