  'Host executable names or paths, without shell quoting. Agent overrides take precedence. New terminals use these shell settings.':
    'Имена или пътеки на изпълними файлове на хоста, без кавички на обвивката. Замените на агента имат предимство. Новите терминали използват тези настройки на обвивката.',
  'Loading {value0} settings…': 'Настройките на {value0} се зареждат...',
