  'Enable agent computer use on this computer':
    'Разрешете използването на компютър на агент на този компютър',
  'Grants writable agents access to this computer’s desktop. Read-only agents are excluded. The user and agents share the desktop and app state.':
    'Предоставя достъп на агенти с възможност за запис до работния плот на този компютър. Агентите само за четене са изключени. Потребителят и агентите споделят работния плот и състоянието на приложението.',
  'Leave Cua Driver empty to detect it on this computer’s PATH or in its standard installation folder. Changes apply to new agent turns.':
    'Оставете Cua Driver празен, за да го откриете в PATH на този компютър или в неговата стандартна инсталационна папка. Промените важат за редовете на новите агенти.',
  '1. Install on this computer': '1. Инсталирайте на този компютър',
  'Run the official installer on the runtime host, then refresh status. It downloads and installs CuaDriver; no Cua account is required.':
    'Стартирайте официалния инсталатор на хоста за изпълнение, след което опреснете състоянието. Изтегля и инсталира CuaDriver; не се изисква акаунт в Cua.',
  'Minimal Linux systems need libxi6 and at-spi2-core. GNOME needs Cua’s bundled WinRects helper; see the installation guide.':
    'Минималните Linux системи се нуждаят от libxi6 и at-spi2-core. GNOME се нуждае от помощния WinRects на Cua; вижте ръководството за инсталиране.',
  'Install and set up Cua Driver': 'Инсталирайте и настройте Cua Driver',
  'Detect / check Cua Driver': 'Откриване / проверка на Cua Driver',
  '2. Permissions & desktop access': '2. Разрешения и достъп до работния плот',
  '3. Agent MCP, skills & hooks': '3. Агент MCP, умения и куки',
  '4. Computer History (optional preview)':
    '4. История на компютъра (предварителен преглед по избор)',
  'Grant macOS Accessibility and Screen Recording to CuaDriver and accept its relaunch. Test desktop access lists apps without changing them. Daemon controls affect active computer-use sessions.':
    'Предоставете macOS достъпност и запис на екрана на CuaDriver и приемете повторното му стартиране. Тестът за достъп до работния плот изброява приложенията, без да ги променя. Контролите на Daemon засягат активните сесии за използване на компютър.',
  'Save the computer-use switch for automatic dovo_cua MCP on new writable turns. No manual MCP registration is needed. Install the optional official skill pack; installation links detected agents on this computer.':
    'Запазете превключвателя за използване на компютъра за автоматичен dovo_cua MCP на нови завъртания с възможност за запис. Не е необходима ръчна MCP регистрация. Инсталирайте незадължителния официален пакет с умения; инсталационни връзки, открити агенти на този компютър.',
  'Opt-in, encrypted, metadata-only history. Enable may restart the daemon. Disable keeps recorded data; pause temporarily stops recording. Unsupported builds report an error. Data stays on the runtime host; View recent history retrieves up to 20 events here.':
    'Включване, криптирана история само с метаданни. Активирането може да рестартира демона. Деактивиране запазва записани данни; пауза временно спира записа. Неподдържаните компилации съобщават за грешка. Данните остават на хоста по време на изпълнение; Прегледът на скорошната история извлича до 20 събития тук.',
