  'Relay fallback': 'Резервно реле',
  'The computer must allow relay in its pairing QR. For a Direct-only pairing, generate a new Dovo-enabled QR on the computer and pair again.':
    'Компютърът трябва да позволява реле в своя QR за сдвояване. За сдвояване само директно, генерирайте нов QR с активиран Dovo на компютъра и сдвоете отново.',
  'Scan pairing QR code': 'Сканирайте QR кода за сдвояване',
  'Point your camera at the QR code shown by Dovo Studio or the server’s pair command.':
    'Насочете камерата си към QR кода, показан от Dovo Studio или командата за двойка на сървъра.',
  'Allow camera access to scan a pairing code. You can also enter the address and code manually.':
    'Разрешаване на достъп до камерата за сканиране на код за сдвояване. Можете също да въведете адреса и кода ръчно.',
