  'Memory limit (MB)': 'Ограничение на паметта (MB)',
  "Runs each new thread's agent, its commands and its terminals in a local Docker or Podman container. Only the checkout and the selected harness login are mounted. Running threads keep their setting.":
    'Изпълнява агента на всеки нов разговор, командите му и терминалите му в локален контейнер на Docker или Podman. Монтират се само работното копие и данните за вход на избрания агент. Текущите разговори запазват настройката си.',
  'Without network access the harness cannot reach its model API unless that API runs inside the sandbox. Package installs and web requests also fail.':
    'Без достъп до мрежата агентът не може да достигне API на своя модел, освен ако този API не работи в пясъчника. Инсталирането на пакети и уеб заявките също се провалят.',
