    'Разговорът може да промени това преди първото си съобщение.',
  'Full network access. The agent can reach any address the host can.':
    'Пълен достъп до мрежата. Агентът може да достигне всеки адрес, до който достига хостът.',
  'Leave empty for no limit.': 'Оставете празно за без ограничение.',
